/* @lc app=leetcode id=1498 lang=kotlin */ class Solution { fun numSubseq(nums: IntArray, target: Int): Int = nums.sorted().let { a -> (1..a.size).runningFold(1L) { x, _ -> x * 2 % 1_000_000_007 }.let { pw -> generateSequence(Triple(0, a.size - 1, 0L)) { (l, r, s) -> if (l > r) null else if (a[l] + a[r] <= target) Triple(l + 1, r, (s + pw[r - l]) % 1_000_000_007) else Triple(l, r - 1, s) }.last().third.toInt() } } }